import {installExerciseDrag,moveExercise} from './reorder.js';
import {periodStart,progressWorkouts,workoutTotals,loadSeries,loadRecords} from './progress.js';
import {exerciseCatalogue,exerciseRecords,exerciseStats,searchExercises,insertLibraryExercise} from './exercises.js';
import {open,commit,read,clone,migrate,KEY,recover,SANDBOX} from './store.js';
import {matches,previousSet,startSession,isExpired,finishSession,updateSet,highestLoadRecords,cycle,PHASES,enabledIndices,toggleSession,importProgramme,phaseName,sessionPhase,setProgrammeMode,duplicateSessionDraft,saveWorkoutEdits,exerciseGroup,exerciseBlocks,groupExercises,ungroupExercises,cleanExerciseGroups,sessionOrder,saveSessionOrder} from './model.js';
const LB=2.2046226218,$=id=>document.getElementById(id),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let failedMutation=null,finishBusy=false,orderDraft=null;
let progressDays=28,progressPhase='all',progressExercise=null,progressCatalogue=[];
let catalogue=[],exerciseQuery='',exerciseList='logged',exerciseFocus=null,exercisePhase='all',pickerTarget=null,pickerQuery='',historyReturn='history';
let s,page='training',selected=0,expanded=new Set([0]),referenceOpen=new Set(),editor=null,detail=null,summary=null,filter='all',phaseFilter='all',comparison='current',saveError='',toastTimer;
const channel='BroadcastChannel' in window?new BroadcastChannel('training-log-changes'+(SANDBOX?'-qa':'')):null;
const display=kg=>s.settings.unit==='lb'?kg*LB:kg,base=v=>s.settings.unit==='lb'?v/LB:v;
const fmt=(n,d=2)=>Number(n).toLocaleString('en-AU',{maximumFractionDigits:d});
const total=w=>w.exercises.reduce((n,e)=>n+e.sets.filter(z=>z.done).length,0);
const planned=w=>w.exercises.reduce((n,e)=>n+e.sets.length,0);
const duration=w=>Math.max(0,(w.ended??Date.now())-w.started);
const elapsed=ms=>`${Math.floor(ms/3600000)>0?Math.floor(ms/3600000)+':':''}${String(Math.floor(ms/60000)%60).padStart(2,'0')}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}`;
const date=t=>new Date(t).toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'});
const button=(label,action,cls='ghost',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const icons={training:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M7 9h10M7 14h6"/>',history:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',settings:'<path d="m9 3-1 3-3 1-2 5 2 5 3 1 1 3h6l1-3 3-1 2-5-2-5-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>'};
function flash(message){$('status').innerHTML=`<div class="toast">${esc(message)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('status').innerHTML='',2400);}
function theme(){const light=s.settings.theme==='light'||(s.settings.theme==='system'&&matchMedia('(prefers-color-scheme: light)').matches);document.body.classList.toggle('light',light);document.querySelector('meta[name=theme-color]').content=light?'#f3f2ed':'#101820';}
function fail(e){saveError='Could not save. Keep this page open and retry. Your last saved records have been preserved.';render();flash(e.message||'Saving failed');}
async function change(fn,redraw=true){for(const el of document.querySelectorAll('.saved'))el.textContent='Saving…';try{s=await commit(fn);saveError='';failedMutation=null;channel?.postMessage(s.revision);if(redraw)render();else for(const el of document.querySelectorAll('.saved'))el.textContent='✓ Saved on this device';return true;}catch(e){failedMutation=fn;fail(e);return false;}}
function lastExercise(ex,phase=s.active?.phase??null){for(let j=s.history.length-1;j>=0;j--){if((s.history[j].phase??null)!==phase)continue;const prev=s.history[j].exercises.find(x=>matches(x,ex));if(prev?.sets.some(z=>z.done))return {ex:prev,workout:s.history[j]};}return null;}
const lastSet=(ex,i)=>previousSet(s,ex,i,s.active?.phase??null);
const records=w=>highestLoadRecords(s,w);
function heading(eyebrow,title,right=''){return `<header><div><div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1></div>${right}</header>`;}
function loadChart(series,exercise,days,now){if(!series.length)return '<p class="small muted note">No logged sets for this exercise in the selected period and range.</p>';const width=360,height=205,left=52,right=18,top=23,bottom=38,plotW=width-left-right,plotH=height-top-bottom;const values=series.map(p=>display(p.load)),min=Math.min(...values),max=Math.max(...values),padding=Math.max((max-min)*.12,max*.025,.5),low=Math.max(0,min-padding),high=max+padding;const start=periodStart(days,now)??series[0].started,end=Math.max(now,start+1),x=t=>left+(t-start)/(end-start)*plotW,y=value=>top+(high-value)/(high-low)*plotH;const points=series.map((p,i)=>`${x(p.started).toFixed(2)},${y(values[i]).toFixed(2)}`).join(' ');return `<svg class="load-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Highest logged load per workout for ${esc(exercise.name)} in ${s.settings.unit}"><title>${esc(exercise.name)} · logged load history</title><desc>Each point is the highest actual logged weight in one workout. Dates and exact values are listed below the chart.</desc>${[0,.5,1].map(f=>{const value=low+(high-low)*f,cy=y(value);return `<line x1="${left}" y1="${cy}" x2="${width-right}" y2="${cy}" class="chart-grid"/><text x="${left-8}" y="${cy+4}" text-anchor="end">${fmt(value,1)}</text>`;}).join('')}${series.length>1?`<polyline points="${points}" class="chart-line"/>`:''}${series.map((p,i)=>`<circle cx="${x(p.started)}" cy="${y(values[i])}" r="4.5" class="chart-point"><title>${date(p.started)} · ${fmt(values[i])} ${s.settings.unit}</title></circle>`).join('')}<text x="${left}" y="${height-12}">${new Date(start).toLocaleDateString('en-AU',{day:'numeric',month:'short'})}</text><text x="${width-right}" y="${height-12}" text-anchor="end">Today</text><text x="${left}" y="12">${s.settings.unit}</text></svg>`;}
function trainingProgress(){const now=Date.now(),workouts=progressWorkouts(s,{days:progressDays,phase:progressPhase,now}),totals=workoutTotals(workouts),prs=loadRecords(s,workouts);progressCatalogue=exerciseCatalogue(s).filter(e=>e.stats.sessions);if(!progressExercise||!progressCatalogue.some(e=>matches(e.exercise,progressExercise)))progressExercise=progressCatalogue[0]?clone(progressCatalogue[0].exercise):null;const series=progressExercise?loadSeries(workouts,progressExercise):[];return heading('YOUR TRAINING','Progress')+trainingTabs('progress')+`<div class="comparison-tabs" role="group" aria-label="Progress period">${[[28,'4 weeks'],[84,'12 weeks'],[0,'All time']].map(([days,label])=>button(label,'progressPeriod:'+days,'ghost '+(progressDays===days?'active':''),`aria-pressed="${progressDays===days}"`)).join('')}</div><label class="field"><span>Training range</span><select id="progress-phase"><option value="all" ${progressPhase==='all'?'selected':''}>All ranges</option>${[...PHASES,'Earlier'].map(p=>`<option value="${p}" ${progressPhase===p?'selected':''}>${p==='Earlier'?'No tag / earlier':phaseName(p)}</option>`).join('')}</select></label><div class="statgrid progress-totals">${[['Workouts',totals.workouts],['Logged sets',totals.sets],['Total reps',fmt(totals.reps)],['Volume ('+s.settings.unit+' × reps)',fmt(display(totals.volume),0)]].map(([label,value])=>`<div class="card stack"><span class="small muted">${label}</span><strong>${value}</strong></div>`).join('')}</div><p class="small muted note">Volume is the sum of logged weight × reps. Unlogged sets and running workouts are excluded.</p><section class="card"><h2>Exercise load history</h2>${progressExercise?`<label class="field"><span>Exercise</span><select id="progress-exercise">${progressCatalogue.map(entry=>`<option value="${entry.index}" ${matches(entry.exercise,progressExercise)?'selected':''}>${esc(entry.exercise.name)}</option>`).join('')}</select></label><p class="small muted note">Highest logged load in each workout. Points use actual workout dates.</p>${loadChart(series,progressExercise,progressDays,now)}${series.length?`<div class="load-history-list">${[...series].reverse().map(p=>`<div class="load-history-row"><span class="stack"><strong>${fmt(display(p.load))} ${s.settings.unit}</strong><span class="small muted">${date(p.started)} · ${esc(phaseName(p.phase))} · ${p.sets} logged ${p.sets===1?'set':'sets'}</span></span>${button('Workout','progressWorkout:'+esc(p.id))}</div>`).join('')}</div>`:''}`:'<p class="small muted note">Finish a workout with logged sets to build your progress history.</p>'}</section><section class="card"><h2>New load records</h2><p class="small muted note">A higher logged load than your earlier recorded workouts. First appearances do not count as records.</p>${prs.length?prs.map(pr=>`<div class="load-history-row"><span class="stack"><strong>${esc(pr.name)}</strong><span class="small muted">${date(pr.started)} · ${fmt(display(pr.load))} ${s.settings.unit}</span></span>${button('Workout','progressWorkout:'+esc(pr.id))}</div>`).join(''):'<p class="small muted note">No new load records in this selection.</p>'}</section>`;}
function sessionOrderPage(){if(!orderDraft)return training();return heading('YOUR PROGRAMME','Session order',button('Cancel','cancelOrder'))+`<div class="card"><p class="small muted note">Use the arrows to change the sequence, then Save order. Your current next workout and completed sessions stay unchanged. Paused sessions keep their place and are skipped during training.</p></div>${orderDraft.indices.map((index,position)=>{const t=orderDraft.labels[index];return `<div class="workout-option"><span class="stack order-session-name"><strong>${position+1}. ${esc(t.name)}</strong><span class="small muted">${t.enabled===false?'Paused':'Active'}${index===orderDraft.next?' · Current next workout':''}</span></span><div class="inline-actions order-arrows">${button('↑',`orderMove:${position}:-1`,'ghost',`aria-label="Move ${esc(t.name)} up" ${position===0?'disabled':''}`)}${button('↓',`orderMove:${position}:1`,'ghost',`aria-label="Move ${esc(t.name)} down" ${position===orderDraft.indices.length-1?'disabled':''}`)}</div></div>`;}).join('')}<div class="card">${button('Save order','saveOrder','bigbtn')}</div>`;}
function trainingTabs(tab='programme'){return `<div class="comparison-tabs training-tabs" role="group" aria-label="Training views">${button('Programme','go:training','ghost '+(tab==='programme'?'active':''),`aria-pressed="${tab==='programme'}"`)}${button('Exercises','go:exercises','ghost '+(tab==='exercises'?'active':''),`aria-pressed="${tab==='exercises'}"`)}${button('Progress','go:progress','ghost '+(tab==='progress'?'active':''),`aria-pressed="${tab==='progress'}"`)}</div>`;}
function exerciseSetText(exercises){return exercises.flatMap(ex=>ex.sets.filter(z=>z.done).map(z=>`${fmt(display(z.weight))} ${s.settings.unit} × ${z.reps}`)).join(' · ');}
function exerciseLibrary(){if(exerciseFocus)return exerciseDetailPage();catalogue=exerciseCatalogue(s);return heading('YOUR EXERCISES','Exercises')+trainingTabs('exercises')+`<form id="exercise-search" class="library-search"><label class="field"><span>Search your exercises</span><input type="search" name="query" maxlength="120" value="${esc(exerciseQuery)}" placeholder="Exercise or machine name"></label><button class="ghost" type="submit">Search</button></form><div class="comparison-tabs" role="group" aria-label="Exercise list">${button('Logged exercises','exerciseList:logged','ghost '+(exerciseList==='logged'?'active':''))}${button('All my exercises','exerciseList:all','ghost '+(exerciseList==='all'?'active':''))}</div><p class="small muted note">${exerciseList==='logged'?'Most recently logged first.':'Includes programme exercises with no logged history.'}</p><div id="exercise-results">${exerciseLibraryResults()}</div>`;}
function exerciseLibraryResults(){const entries=searchExercises(catalogue,exerciseQuery).filter(e=>exerciseList==='all'||e.stats.sessions);return entries.length?entries.map(entry=>`<button class="workout-option library-entry" data-action="exerciseDetail:${entry.index}"><span class="stack"><strong>${esc(entry.exercise.name)}</strong><span class="small muted">${entry.stats.sessions?`${entry.stats.sessions} ${entry.stats.sessions===1?'session':'sessions'} · ${date(entry.stats.latest.workout.started)}`:'Programme only · no logged sets'}</span>${entry.stats.latest?`<span class="small">${esc(exerciseSetText(entry.stats.latest.exercises))}</span>`:''}</span><span aria-hidden="true">›</span></button>`).join(''):'<div class="card"><h2>No matching exercises</h2><p class="small muted note">Log an exercise to build its history, or choose All my exercises to see your programme.</p></div>';}
function exerciseDetailPage(){const records=exerciseRecords(s,exerciseFocus,exercisePhase),stats=exerciseStats(records);return heading('EXERCISE HISTORY',exerciseFocus.name,button('Back','exerciseBack'))+`<div class="comparison-tabs" role="group" aria-label="Exercise history range">${['all',...PHASES,'Earlier'].map(p=>button(p==='all'?'All':p==='Earlier'?'No tag':phaseName(p),'exercisePhase:'+p,'ghost '+(exercisePhase===p?'active':''))).join('')}</div><div class="card"><div class="row"><span class="stack"><span class="small muted">Recorded sessions</span><strong>${stats.sessions}</strong></span><span class="stack"><span class="small muted">Heaviest logged load</span><strong>${stats.heaviest===null?'—':fmt(display(stats.heaviest))+' '+s.settings.unit}</strong></span></div>${stats.latest?`<div class="divider"></div><span class="small muted">Latest · ${date(stats.latest.workout.started)}</span><p class="small">${esc(exerciseSetText(stats.latest.exercises))}</p>`:'<p class="small muted note">No logged sets in this range.</p>'}</div>${records.map(({workout,exercises})=>`<section class="card exercise-history"><div class="row"><span class="stack"><strong>${esc(workout.name)}</strong><span class="small muted">${date(workout.started)} · ${esc(phaseName(workout.phase))}</span></span>${button('Workout','exerciseWorkout:'+esc(workout.id))}</div>${exercises.map(ex=>tiles(ex)).join('')}</section>`).join('')}`;}
function exercisePickerPage(){catalogue=exerciseCatalogue(s);return heading('REUSE AN EXERCISE',pickerTarget===null?'Add exercise':'Replace exercise',button('Back','pickerBack'))+`<p class="small muted note">Choosing an exercise updates your draft. Save the session editor to apply it.</p><form id="picker-search" class="library-search"><label class="field"><span>Search your library</span><input name="query" type="search" maxlength="120" value="${esc(pickerQuery)}" placeholder="Exercise or machine name"></label><button type="submit" class="ghost">Search</button></form><div id="picker-results">${exercisePickerResults()}</div><form id="custom-exercise" class="card"><h2>Create a new exercise</h2><label class="field"><span>Name</span><input name="name" maxlength="120" required placeholder="e.g. Seated row · cable machine"></label><p class="small muted note">Only a name is needed. Adjust sets and starting values in the session editor.</p><button class="ghost" type="submit">Use new exercise</button></form>`;}
function exercisePickerResults(){const entries=searchExercises(catalogue,pickerQuery);return entries.length?entries.map(entry=>`<button class="workout-option library-entry" data-action="pickKnown:${entry.index}"><span class="stack"><strong>${esc(entry.exercise.name)}</strong><span class="small muted">${entry.stats.sessions?`${entry.stats.sessions} recorded ${entry.stats.sessions===1?'session':'sessions'}`:'Programme only · no logged sets'}</span></span><span class="small">${pickerTarget===null?'Add':'Use'}</span></button>`).join(''):'<p class="small muted note">No matches. Create a named exercise below.</p>';}
function chooseLibraryExercise(exercise){if(!editor||editor.history)return;const old=pickerTarget===null?null:editor.draft.exercises[pickerTarget];if(editor.active&&old?.sets.some(z=>z.done)&&!confirm('Replace this exercise and remove its logged sets from today’s workout?'))return;insertLibraryExercise(editor.draft,exercise,{active:!!editor.active,index:pickerTarget,state:s});pickerTarget=null;page='editor';render();window.scrollTo(0,0);}
function training(){if(!s.templates[selected]||s.templates[selected].enabled===false)selected=s.next;const t=s.templates[selected],c=cycle(s);return heading('YOUR PROGRAMME','Training',`<span class="pill">${c.count}-session cycle</span>`)+trainingTabs()+`<section class="card hero"><div class="hero-heading"><div class="eyebrow">${selected===s.next?'NEXT WORKOUT':'SELECTED WORKOUT'}</div><span class="range-pill">${esc(phaseName(sessionPhase(s,t)))}</span></div><h2 class="hero-title">${esc(t.name)}</h2><div class="hero-metrics"><span><strong>${t.exercises.length}</strong> exercises</span><span><strong>${t.exercises.reduce((n,e)=>n+e.sets,0)}</strong> planned sets</span></div>${s.programme.mode==='manual'?'':phaseStrip(c)}${selected!==s.next?`<p class="small note muted">${s.programme.mode==='manual'?'Start this session now; the next active session follows it.':'This session runs first. Other unfinished sessions stay in this rotation.'}</p>`:''}${button(s.active?'Resume Workout →':'Start Workout →',s.active?'resume':`start:${selected}`,'bigbtn start-workout',!t.exercises.length&&!s.active?'disabled':'')}${programmePreview(t)}<div class="inline-actions hero-actions">${button('Edit name & tag',`edit:${selected}`)}${button('Duplicate session',`duplicate:${selected}`)}</div>${t.example?'<p class="small muted note example-note">Example programme and starting loads. Edit these to match your training.</p>':''}</section><details class="card programme-settings"><summary><span>Training structure</span><span class="small muted">${s.programme.mode==='manual'?'Session tags':'Automatic rotation'}</span></summary><form id="programme-mode"><label class="field"><span>How to choose training ranges</span><select name="mode" ${s.active?'disabled':''}><option value="auto" ${s.programme.mode!=='manual'?'selected':''}>Automatic Heavy → Medium → Light rotation</option><option value="manual" ${s.programme.mode==='manual'?'selected':''}>Use my session tags</option></select></label><p class="small muted note">${s.programme.mode==='manual'?'Session names and tags are yours to choose. Sessions repeat in sequence without an automatic range change.':'Two full rotations per range. Each session can follow the rotation or use its own tag.'}${s.active?' Finish your current workout before changing the structure.':''}</p><button class="ghost" type="submit" ${s.active?'disabled':''}>Save training structure</button></form></details><div class="section-title"><h2>Programme sessions</h2><div class="session-tools">${button('+ Add session','addSession')}${button('Reorder sessions','reorderSessions','ghost',s.active?'disabled':'')}</div></div>${s.active?'<p class="small muted note">Finish your current workout to change the session order.</p>':''}${sessionOrder(s).map((i,position)=>{const t=s.templates[i];return `<div class="workout-option session-row ${selected===i?'selected':''}"><button class="exhead" data-action="choose:${i}" aria-pressed="${selected===i}" ${t.enabled===false?'disabled':''}><span class="session-number" aria-hidden="true">${String(position+1).padStart(2,'0')}</span><span class="stack"><strong>${esc(t.name)} ${s.next===i?'<span class="badge">NEXT</span>':''}</strong><span class="small muted">${t.exercises.length} exercises · ${esc(Object.hasOwn(t,'phase')?phaseName(t.phase):s.programme.mode==='manual'?'No tag':'Follows rotation')} · ${t.enabled===false?'Paused':t.example?'Example':'Your programme'}</span></span></button>${button('Edit',`edit:${i}`,'ghost',`aria-label="Edit ${esc(t.name)}"`)}</div>`;}).join('')}`;}
function programmePreview(t){return t.exercises.length?`<details class="programme-preview"><summary>View exercise list</summary><ol>${t.exercises.map(e=>`<li><span class="preview-exercise"><span>${esc(e.name)}${groupBadge(t.exercises,e)}</span><span class="subtle">${e.sets} ${e.sets===1?'set':'sets'}</span></span></li>`).join('')}</ol></details>`:'<p class="small muted note">Add an exercise to get started.</p>';}
function phaseStrip(c){return `<div class="phase-label">${phaseName(c.phase)} · rotation ${c.rotation} of 2 · ${c.completed.length}/${c.count} sessions finished</div><div class="phase-steps" aria-label="Heavy twice, Medium twice, Light twice">${Array.from({length:6},(_,i)=>`<span class="${i===c.step?'current':''}">${phaseName(PHASES[Math.floor(i/2)])}<br><b>${i%2+1}</b></span>`).join('')}</div>`;}
function previous(ex,i){const phase=comparison==='current'?(s.active?.phase??null):comparison==='Earlier'?null:comparison;const old=lastExercise(ex,phase);const tabs=`<div class="comparison-tabs" role="group" aria-label="Previous-session phase">${[...PHASES,'Earlier'].map(p=>button(p==='Earlier'?'No tag':phaseName(p),'compare:'+p,'ghost '+((phase??'Earlier')===p?'active':''))).join('')}</div>`;return `<details class="previous-reference" data-previous="${i}" ${referenceOpen.has(i)?'open':''}><summary><span>Previous performance</span><span class="reference-summary">${old?date(old.workout.started):'No '+esc(phaseName(phase))+' log yet'}</span></summary><div class="reference-content">${tabs}${old?`<div class="row"><span class="subtle">${esc(phaseName(phase))}</span><span class="subtle">${date(old.workout.started)}</span></div>${tiles(old.ex)}<p class="subtle">Reference only · current values stay unchanged.</p>`:`<p class="small muted note">No ${esc(phaseName(phase))} log yet. Starting values are editable.</p>`}</div></details>`;}
function restBar(a){return s.settings.restTimer?`<div class="rest-bar"><span>Rest <strong data-rest>${a.restStarted?elapsed(Math.max(0,Date.now()-a.restStarted)):'—'}</strong></span>${button('Reset','restReset','ghost',a.restStarted?'':'disabled')}</div>`:'';}
function quantity(ex,i,z,j,key){const isWeight=key==='weight',val=isWeight?fmt(display(z.weight),s.settings.unit==='lb'?1:4).replace(/,/g,''):z.reps;return `<div class="control-row"><label for="${key}-${i}-${j}">${isWeight?`Weight <span>(${s.settings.unit})</span>`:'Reps'}</label><div class="qty">${button('−',`adjust:${i}:${j}:${key}:-1`,'',`aria-label="Decrease ${key} set ${j+1}"`)}<input id="${key}-${i}-${j}" aria-label="${isWeight?'Weight':'Repetitions'} set ${j+1}" type="number" inputmode="${isWeight?'decimal':'numeric'}" min="0" ${isWeight?'step="any"':'step="1" max="999"'} value="${ex.needsSetup&&Number(val)===0?'':val}" data-set="${i}:${j}:${key}">${button('+',`adjust:${i}:${j}:${key}:1`,'',`aria-label="Increase ${key} set ${j+1}"`)}</div></div>`;}
const exerciseComplete=ex=>ex.sets.length>0&&ex.sets.every(z=>z.done);
function loggedSetSummary(ex){const logged=ex.sets.filter(z=>z.done);return logged.length?`<span class="exercise-log"><span class="muted">Logged:</span> ${logged.map(z=>`${fmt(display(z.weight))} ${s.settings.unit} × ${z.reps}`).join(' · ')}</span>`:'';}
function exerciseGroupHeader(group){return `<div class="exercise-group-heading"><h2>${esc(group.title)}</h2><span class="group-count">${group.members.length} exercises together</span></div><p class="group-instruction">One set from each exercise completes a round. Rest after the full round.</p>`;}
function activeExercise(a,i){const ex=a.exercises[i],group=exerciseGroup(a.exercises,ex);return `<section class="card exercise ${exerciseComplete(ex)?'complete':''}" id="exercise-${i}"><button class="exhead" data-action="expand:${i}" aria-expanded="${expanded.has(i)}" aria-controls="body-${i}"><span class="stack"><strong>${i+1}. ${esc(ex.name)}</strong>${group?`<span class="group-member-count">Exercise ${group.position} of ${group.members.length}</span>`:''}<span class="exercise-status"><span class="small muted">${ex.sets.filter(z=>z.done).length}/${ex.sets.length} sets logged</span>${exerciseComplete(ex)?'<span class="badge">✓ Complete</span>':''}</span>${loggedSetSummary(ex)}</span><span aria-hidden="true" style="color:var(--gold);font-size:24px">${expanded.has(i)?'−':'+'}</span></button>${expanded.has(i)?`<div class="exbody" id="body-${i}">${ex.needsSetup?'<p class="small muted note">Enter your starting values and check the planned set count before logging.</p>':''}${previous(ex,i)}<div class="current-sets" aria-label="${esc(ex.name)} current sets">${ex.sets.map((z,j)=>`<div class="setcard compact-set ${z.done?'done':''}"><div class="set-row-heading"><strong>Set ${j+1}</strong>${button(z.done?'✓ Logged · Undo':'Log Set '+(j+1),`log:${i}:${j}`,'bigbtn set-log')}</div><div class="set-fields">${quantity(ex,i,z,j,'weight')}${quantity(ex,i,z,j,'reps')}</div></div>`).join('')}</div></div>`:''}</section>`;}
function activeExerciseList(a){return exerciseBlocks(a.exercises).map(({group,indices})=>group?`<section class="exercise-group" aria-label="${esc(group.title)}">${exerciseGroupHeader(group)}${indices.map(i=>activeExercise(a,i)).join('')}</section>`:activeExercise(a,indices[0])).join('');}
function active(){const a=s.active;if(!a)return training();return heading('ACTIVE WORKOUT',a.name,button('Programme','go:training'))+`<div class="card workout-status"><div class="status-topline"><span class="range-pill">${esc(phaseName(a.phase))}</span><span class="saved">✓ Saved on this device</span></div><div class="workout-metrics"><div><strong>${total(a)}<span> / ${planned(a)}</span></strong><span class="metric-label">Sets logged</span></div><div><strong class="time" data-clock>${elapsed(duration(a))}</strong><span class="metric-label">Workout time</span></div></div><div class="progressbar"><span style="width:${planned(a)?100*total(a)/planned(a):0}%"></span></div>${restBar(a)}</div><div class="inline-actions exercise-visibility">${button('Edit workout','editToday','ghost','aria-label="Edit today’s workout"')}${button('Expand all','expandAll')}${button('Collapse all','collapseAll')}</div>${activeExerciseList(a)}<div class="card endcard"><h3>Finish session</h3><p class="small muted note">Review any unlogged sets before finishing. You can return to log them or finish with them unlogged.</p>${button('End Workout →','finish','bigbtn goldbtn')}</div>`;}
function tiles(ex){return `<table class="set-table" aria-label="${esc(ex.name)} sets"><colgroup><col class="set-column"><col class="value-column"><col class="value-column"></colgroup><thead><tr><th scope="col">Set</th><th scope="col">${s.settings.unit}</th><th scope="col">Reps</th></tr></thead><tbody>${ex.sets.map((z,j)=>`<tr class="${z.done?'logged-row':'unlogged-row'}"><th scope="row">Set ${j+1}${z.done?'':'<span class="set-status">Not logged</span>'}</th><td>${z.done?fmt(display(z.weight)):'—'}</td><td>${z.done?z.reps:'—'}</td></tr>`).join('')}</tbody></table>`;}
function workoutDetails(w){return exerciseBlocks(w.exercises).map(({group,indices})=>{const content=indices.map(i=>`<div class="divider"></div><h3>${esc(w.exercises[i].name)}</h3>${tiles(w.exercises[i])}`).join('');return group?`<section class="exercise-group record-group"><div class="exercise-group-heading"><h2>${esc(group.title)}</h2><span class="group-count">${group.members.length} exercises together</span></div><div class="record-group-content">${content}</div></section>`:content;}).join('');}
function recordOverview(w){const missing=planned(w)-total(w);return `<section class="card record-overview"><div class="history-top"><time datetime="${new Date(w.started).toISOString()}">${date(w.started)}</time><span class="range-pill">${esc(phaseName(w.phase))}</span></div><div class="workout-metrics"><div><strong>${total(w)}<span> / ${planned(w)}</span></strong><span class="metric-label">Sets logged</span></div><div><strong class="time">${elapsed(duration(w))}</strong><span class="metric-label">Duration</span></div></div>${missing?`<p class="unlogged-notice">${missing} ${missing===1?'set was':'sets were'} not logged.</p>`:'<p class="record-complete">✓ All planned sets logged</p>'}${w.auto?'<p class="small muted note">Auto-finished at your last workout interaction.</p>':''}</section>`;}
function history(){if(detail){const w=s.history.find(x=>x.id===detail);if(w)return heading('WORKOUT RECORD',w.name,button('Back','historyBack'))+recordOverview(w)+`<section class="card record-sets"><div class="row"><h2>Workout sets</h2>${button('Edit','correct:'+w.id,'ghost',`aria-label="Edit recorded sets for ${esc(w.name)}"`)}</div>${workoutDetails(w)}</section>`;detail=null;}
 const list=[...s.history].reverse().filter(w=>(filter==='all'||String(w.templateIndex)===filter)&&(phaseFilter==='all'||(w.phase??'Earlier')===phaseFilter));return heading('YOUR RECORDS','History',`<span class="pill">${s.history.length} workouts</span>`)+`<label class="field"><span>Phase</span><select class="filter" id="phase-filter"><option value="all">All phases</option>${[...PHASES,'Earlier'].map(p=>`<option value="${p}" ${phaseFilter===p?'selected':''}>${p==='Earlier'?'No tag / earlier':phaseName(p)}</option>`).join('')}</select></label><label class="field"><span>Workout</span><select class="filter" id="history-filter"><option value="all">All sessions</option>${sessionOrder(s).map(i=>{const t=s.templates[i];return `<option value="${i}" ${filter===String(i)?'selected':''}>${esc(t.name)}</option>`;}).join('')}</select></label>${list.length?list.map(historyCard).join(''):`<div class="card empty"><div class="empty-mark">◷</div><h2>${s.history.length?'No matching workouts':'No workouts yet'}</h2><p class="small muted note">${s.history.length?'Choose another session to see your records.':'Your first finished session will appear here with the sets you actually logged.'}</p>${button('Go to Programme','go:training')}</div>`}`;}
function historyCard(w){const count=total(w);return `<button class="workout-option history-entry" data-action="history:${esc(w.id)}"><span class="history-main"><span class="history-top"><time datetime="${new Date(w.started).toISOString()}">${date(w.started)}</time><span class="pill">${esc(phaseName(w.phase))}</span></span><strong class="history-name">${esc(w.name)}</strong><span class="history-metrics"><span><strong>${count}<span class="metric-denominator"> / ${planned(w)}</span></strong><span>Sets logged</span></span><span><strong>${elapsed(duration(w))}</strong><span>Duration</span></span></span>${planned(w)>count?`<span class="history-unlogged">${planned(w)-count} ${planned(w)-count===1?'set':'sets'} not logged</span>`:''}${w.auto?'<span class="subtle">Auto-finished at last activity</span>':''}${records(w).length?'<span class="small success">↑ New highest recorded load</span>':''}</span><span class="history-chevron" aria-hidden="true">›</span></button>`;}
function recordedWorkout(w){return workoutDetails(w);}
function summaryPage(){const w=s.history.find(x=>x.id===summary);if(!w){page='training';return training();}const prs=records(w);return heading(w.auto?'AUTO-FINISHED':'WORKOUT SAVED',w.name)+recordOverview(w)+`<section class="card saved-next"><span class="eyebrow">NEXT IN YOUR CYCLE</span><h2>${esc(s.templates[s.next].name)}</h2>${prs.length?`<p class="small success">↑ New highest recorded load: ${prs.map(esc).join(', ')}</p>`:''}</section><section class="card record-sets"><h2>Workout sets</h2>${recordedWorkout(w)}</section>${button('Done →','done','bigbtn')}`;}
function settings(){return heading('PREFERENCES','Settings')+`<div class="card"><h2>Appearance</h2><div class="inline-actions" style="margin-top:14px">${['system','light','dark'].map(x=>button(x==='system'?'Follow Device':x[0].toUpperCase()+x.slice(1),`theme:${x}`,`ghost ${s.settings.theme===x?'active':''}`,`aria-pressed="${s.settings.theme===x}"`)).join('')}</div></div><div class="card"><h2>Weight units</h2><p class="small muted">One unit for all lifting weights.</p><div class="inline-actions">${['kg','lb'].map(x=>button(x,`unit:${x}`,`ghost ${s.settings.unit===x?'active':''}`,`aria-pressed="${s.settings.unit===x}"`)).join('')}</div></div><form id="preferences" class="card"><h2>Training controls</h2><label class="field"><span><input type="checkbox" name="restTimer" ${s.settings.restTimer?'checked':''}> Show count-up rest timer</span></label><label class="field"><span>Default weight increment (${s.settings.unit})</span><input type="number" name="increment" min="0.01" step="any" required value="${fmt(display(s.settings.increment),4).replace(/,/g,'')}"></label><label class="field"><span>Auto-end after inactivity (2–24 hours)</span><input name="inactivityHours" type="number" min="2" max="24" step="1" required value="${s.settings.inactivityHours}"></label><p class="small muted note">The app checks when you return. Auto-finished duration stops at your last workout interaction.</p><button class="ghost" type="submit">Save preferences</button></form><div class="card"><h2>Your programme</h2><p class="small muted note">Add and rename sessions from Programme. Importing a programme changes future templates only; your history stays intact. Finish any running workout first. Import starts a fresh rotation in the current phase.</p><label class="field"><span>Import programme file</span><input id="programme-import" type="file" accept=".json,application/json"></label></div><div class="card"><h2>Your data</h2><p class="small muted note">Saved locally in this browser or Home Screen app. No cloud backup. Clearing website data or changing phones can remove your records.</p>${button('Download backup','backup')}<label class="field"><span>Restore backup</span><input id="restore" type="file" accept=".json,application/json"></label></div><div class="card"><h2>Use on your iPhone</h2><p class="small muted note">Open the published URL in Safari. Tap Share → Add to Home Screen → Add. Start logging in that Home Screen app and keep using it so all records stay in the same place.</p><p class="small muted note">After the first online visit, the app works offline. Updates apply when you reopen it without a running workout.</p><span class="subtle">Clearer workout records · v0.14.2</span></div>`;}
function groupBadge(exercises,ex){const g=exerciseGroup(exercises,ex);return g?`<span class="group-badge" title="${esc(g.members.map(e=>e.name).join(' + '))}">${esc(g.title)} · ${g.position}/${g.members.length}</span>`:'';}
function groupingPanel(){if(editor.history)return '';const exercises=editor.draft.exercises,seen=new Set();const groups=exercises.flatMap((ex,i)=>{const g=exerciseGroup(exercises,ex);if(!g||seen.has(g.id))return [];seen.add(g.id);return [`<div class="group-summary"><span><strong>${esc(g.title)}</strong><span class="small muted">${g.members.map(e=>esc(e.name)).join(' + ')}</span></span>${button('Ungroup',`groupClear:${i}`)}</div>`];});return `<details class="card group-editor"><summary>Supersets &amp; giant sets${groups.length?` · ${groups.length} ${groups.length===1?'group':'groups'}`:''}</summary><p class="small muted note">Select two exercises for a superset, or three or more for a giant set. You can select exercises anywhere in the list. Their order stays unchanged.</p>${groups.join('')}${exercises.map((ex,i)=>`<label class="group-choice"><input type="checkbox" name="group-select-${i}"><span>${i+1}. ${esc(ex.name)}${groupBadge(exercises,ex)}</span></label>`).join('')}<div class="inline-actions">${button('Group selected','groupSelected')}${button('Ungroup selected','ungroupSelected')}</div><p class="small muted note">Changes apply when you save this editor. During a grouped round, log one set from each exercise; rest starts when the whole round is logged.</p></details>`;}
function sessionTagField(){const value=Object.hasOwn(editor.draft,'phase')?(editor.draft.phase??'none'):'inherit';return `<label class="field"><span>Session tag · Heavy / Medium / Light</span><select name="phase">${[['inherit',s.programme.mode==='manual'?'No fixed tag (programme default)':'Follow automatic rotation'],['Heavy','Heavy · low rep range'],['Mid','Medium · mid rep range'],['Light','Light · high rep range'],['none','No tag']].map(([key,label])=>`<option value="${key}" ${value===key?'selected':''}>${label}</option>`).join('')}</select></label><p class="small muted note">This labels the session; it does not change your weights or reps. Set your starting values below.</p>`;}
function exerciseDragHandle(i){return `<button type="button" class="ghost drag-handle" data-drag-exercise="${i}" aria-label="Drag exercise ${i+1} to reorder; arrow buttons are also available"><svg viewBox="0 0 16 24" aria-hidden="true">${[5,12,19].map(y=>`<circle cx="5" cy="${y}" r="1.8"/><circle cx="11" cy="${y}" r="1.8"/>`).join('')}</svg><span>Move</span></button>`;}
function setupExerciseDrag(){return installExerciseDrag({root:document,viewport:window,enabled:()=>page==='editor'&&!!editor&&!editor.history,snapshot:snapshotEditor,announce:flash,move:(from,to)=>{if(!editor||editor.history)return;moveExercise(editor.draft.exercises,from,to);const name=editor.draft.exercises[to].name;render();const handle=document.querySelector(`[data-drag-exercise="${to}"]`);handle?.focus({preventScroll:true});handle?.closest('[data-exercise-row]')?.scrollIntoView({block:'nearest'});flash(`${name} moved to position ${to+1}. Save to apply.`);}});}
function todayEditPage(){const a=editor.draft;return heading('EDIT TODAY’S WORKOUT',a.name,button('Cancel','cancelEdit'))+`<form id="editor"><div class="card"><p class="small muted note">Save for today keeps your programme unchanged. Save today &amp; programme also updates this session’s future exercise list and starting values. Past workouts stay unchanged.</p><label class="field"><span>Session name</span><input name="name" maxlength="100" required value="${esc(a.name)}"></label></div>${groupingPanel()}<p class="small muted note">Drag an exercise by its Move handle, or use the arrow buttons. Save to apply the order.</p>${a.exercises.map((ex,i)=>`<section class="editor-row" data-exercise-row="${i}"><div class="editor-drag-row">${groupBadge(a.exercises,ex)}${exerciseDragHandle(i)}</div><label class="field"><span>Exercise ${i+1}</span><input name="exercise-${i}" maxlength="120" required value="${esc(ex.name)}"></label><p class="small muted">${ex.sets.filter(z=>z.done).length} logged · ${ex.sets.length} planned sets</p>${ex.sets.map((z,j)=>`<div class="editor-fields"><label class="field"><span>Set ${j+1} · ${z.done?'logged':'not logged'} · ${s.settings.unit}</span><input name="weight-${i}-${j}" type="number" min="0" step="any" required value="${fmt(display(z.weight),4).replace(/,/g,'')}"></label><label class="field"><span>Reps</span><input name="reps-${i}-${j}" type="number" min="${z.done?1:0}" max="999" step="1" required value="${z.reps}"></label></div>`).join('')}<div class="inline-actions">${button('+ Add set',`todaySet:${i}:add`,'ghost',ex.sets.length>=12?'disabled':'')}${button('Remove last set',`todaySet:${i}:remove`,'ghost',ex.sets.length<=1?'disabled':'')}</div><div class="editor-actions">${button('↑',`todayMove:${i}:-1`,'ghost',`aria-label="Move exercise ${i+1} up" ${i===0?'disabled':''}`)}${button('↓',`todayMove:${i}:1`,'ghost',`aria-label="Move exercise ${i+1} down" ${i===a.exercises.length-1?'disabled':''}`)}${button('Replace',`pickExercise:replace:${i}`)}${button('Remove',`todayRemove:${i}`,'ghost danger')}</div></section>`).join('')}<div class="inline-actions">${button('Choose from library','pickExercise:add')}${button('+ New exercise','todayAdd')}</div><div class="card"><button class="bigbtn" type="submit" value="today">Save for today</button><div style="height:12px"></div><button class="ghost" type="submit" value="programme">Save today &amp; programme</button></div></form>`;}
function snapshotTodayEditor(){const f=new FormData($('editor'));editor.draft.name=String(f.get('name')||'').trim();editor.draft.exercises.forEach((ex,i)=>{ex.name=String(f.get(`exercise-${i}`)||'').trim();ex.sets.forEach((z,j)=>{z.weight=base(Number(f.get(`weight-${i}-${j}`)));z.reps=Number(f.get(`reps-${i}-${j}`));});});}
function editPage(){if(editor.active)return todayEditPage();return heading(editor.history?'CORRECT YOUR RECORD':editor.isCopy?'DUPLICATE SESSION':'EDIT YOUR PROGRAMME',editor.draft.name,button('Cancel','cancelEdit'))+`<form id="editor">${!editor.history&&!editor.isNew?button(editor.draft.enabled===false?'Enable session':'Pause session','pauseSession:'+editor.index,'ghost'):''}<label class="field"><span>Session name</span><input name="name" maxlength="100" required value="${esc(editor.draft.name)}"></label>${!editor.history?sessionTagField():''}${editor.isCopy?'<p class="small muted note">This is a new copy. Rename it or change its tag and exercises, then Save Session to add it to your programme. Cancel leaves your programme unchanged.</p>':''}${editor.history?'<p class="small muted note">Only changes saved with Save Correction affect this historical record.</p>':'<p class="small muted note">Changes affect future workouts. Current and past sessions keep their original exercises.</p>'}${groupingPanel()}${!editor.history?'<p class="small muted note">Drag an exercise by its Move handle, or use the arrow buttons. Save to apply the order.</p>':''}${editor.draft.exercises.map((e,i)=>`<section class="editor-row" data-ex="${i}" data-exercise-row="${i}"><div class="editor-drag-row">${groupBadge(editor.draft.exercises,e)}${!editor.history?exerciseDragHandle(i):''}</div><label class="field"><span>Exercise ${i+1}</span><input name="exercise-${i}" required maxlength="120" value="${esc(e.name)}"></label>${!editor.history&&e.presets?'<p class="small muted">Different per-set starting values are preserved. Changing the default weight/reps applies it to all sets.</p>':''}${editor.history?e.sets.map((z,j)=>`<div class="editor-fields" style="margin-top:12px"><label class="field"><span>Set ${j+1} weight (${s.settings.unit})</span><input type="number" min="0" step="any" required name="weight-${i}-${j}" value="${fmt(display(z.weight),4).replace(/,/g,'')}"></label><label class="field"><span>Reps</span><input type="number" min="0" max="999" step="1" required name="reps-${i}-${j}" value="${z.reps}"></label><label class="wide small"><input type="checkbox" name="done-${i}-${j}" ${z.done?'checked':''}> Logged set</label></div>`).join(''):`<div class="editor-fields"><label class="field"><span>Sets</span><input name="sets-${i}" type="number" min="1" max="12" step="1" required value="${e.sets}"></label><label class="field"><span>Starting reps</span><input name="reps-${i}" type="number" min="0" max="999" step="1" required value="${e.reps}"></label><label class="field"><span>Starting weight (${s.settings.unit})</span><input name="weight-${i}" type="number" min="0" step="any" required value="${fmt(display(e.weight),4).replace(/,/g,'')}"></label><label class="field"><span>Weight step (${s.settings.unit}, optional)</span><input name="increment-${i}" type="number" min="0.01" step="any" value="${e.increment?fmt(display(e.increment),4).replace(/,/g,''):''}" placeholder="Default"></label></div><div class="editor-actions">${button('↑',`move:${i}:-1`,'ghost',`aria-label="Move exercise ${i+1} up" ${i===0?'disabled':''}`)}${button('↓',`move:${i}:1`,'ghost',`aria-label="Move exercise ${i+1} down" ${i===editor.draft.exercises.length-1?'disabled':''}`)}${button('Replace',`pickExercise:replace:${i}`)}${button('Remove',`remove:${i}`,'ghost danger remove')}</div>`}</section>`).join('')}${!editor.history?'<div class="inline-actions">'+button('Choose from library','pickExercise:add')+button('+ New exercise','add')+'</div><div style="height:20px"></div>':''}<button type="submit" class="bigbtn">${editor.history?'Save Correction':'Save Session'}</button></form>`;}
function render(){if(!s)return;theme();if(['active','finishReview'].includes(page)&&!s.active)page='training';$('app').innerHTML=(SANDBOX?'<div class="card small muted">TEST ENVIRONMENT · separate from your real workout records</div>':'')+(saveError?`<div role="alert" class="error-banner"><p>${esc(saveError)}</p>${button('Retry saving','retry')}${button('Download current data','backup')}</div>`:'')+({training,active,history,finishReview,summary:summaryPage,settings,editor:editPage,exercises:exerciseLibrary,exercisePicker:exercisePickerPage,progress:trainingProgress,sessionOrder:sessionOrderPage}[page]||training)();$('nav').innerHTML=`${s.active&&!['active','finishReview'].includes(page)?`<button class="resume" data-action="resume"><span>${esc(s.active.name)} · ${total(s.active)} sets saved</span><strong>Resume →</strong></button>`:''}<div class="nav-inner">${['training','history','settings'].map(x=>`<button data-action="go:${x}" ${page===x||x==='training'&&['active','finishReview','editor','summary','exercises','exercisePicker','progress','sessionOrder'].includes(page)?'class="active" aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true">${icons[x]}</svg>${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div>`;}
async function expire(){let finished=null;const now=Date.now();if(!isExpired(s,now))return null;if(await change(st=>{if(isExpired(st,now))finished=finishSession(st,st.active.id,now,true).id;return st;},false)){if(finished){summary=finished;page='summary';selected=s.next;flash('Inactive workout saved');}return finished;}}
async function go(where){if(page==='sessionOrder'&&orderDraft){if(!confirm('Discard unsaved session order?'))return;failedMutation=null;saveError='';}orderDraft=null;if(editor&&['editor','exercisePicker'].includes(page)&&!confirm('Discard unsaved edits?'))return;const ended=await expire();if(ended){render();return;}editor=null;detail=null;if(where==='history'){filter='all';phaseFilter='all';historyReturn='history';}if(where==='exercises'){exerciseFocus=null;exercisePhase='all';}page=where;render();window.scrollTo(0,0);}
async function start(i){await expire();if(s.active){page='active';render();return;}if(await change(st=>{startSession(st,i,Date.now(),crypto.randomUUID());return st;},false)){expanded=new Set([0]);referenceOpen=new Set();comparison='current';page='active';render();window.scrollTo(0,0);}}
async function activeChange(fn,redraw=true){const id=s.active?.id;if(!id)return;await change(st=>{if(st.active?.id!==id)throw Error('This workout has already ended. Return to Programme.');if(Date.now()-st.active.lastActivity>=st.settings.inactivityHours*3600000)throw Error('This workout has expired. Reopen Training to save it.');fn(st.active,st);st.active.lastActivity=Date.now();return st;},redraw);}
function snapshotEditor(){if(!editor)return;if(editor.active)return snapshotTodayEditor();const f=new FormData($('editor'));editor.draft.name=String(f.get('name')||'').trim();if(!editor.history){const tag=f.get('phase');if(tag==='inherit')delete editor.draft.phase;else editor.draft.phase=tag==='none'?null:tag;}editor.draft.exercises.forEach((e,i)=>{e.name=String(f.get(`exercise-${i}`)||'').trim();if(editor.history){e.sets.forEach((z,j)=>{z.weight=base(Number(f.get(`weight-${i}-${j}`)));z.reps=Number(f.get(`reps-${i}-${j}`));z.done=f.has(`done-${i}-${j}`);});}else{if(e.weight!==base(Number(f.get(`weight-${i}`)))||e.reps!==Number(f.get(`reps-${i}`)))delete e.presets;e.sets=Number(f.get(`sets-${i}`));if(e.presets)e.presets=e.presets.slice(0,e.sets);e.reps=Number(f.get(`reps-${i}`));e.weight=base(Number(f.get(`weight-${i}`)));const inc=f.get(`increment-${i}`);if(inc)e.increment=base(Number(inc));else delete e.increment;}});}
function finishReview(){const a=s.active;if(!a)return training();const missing=planned(a)-total(a);return heading('REVIEW BEFORE FINISHING','Finish workout?')+`<div class="card"><h2>${esc(a.name)}</h2><p class="small muted">${total(a)} of ${planned(a)} sets logged</p><p class="unlogged-notice">${missing} ${missing===1?'set is':'sets are'} still unlogged. Return to log them, or finish with these sets unlogged.</p><div class="finish-actions">${button('Back to workout','resume','bigbtn')}${button(`Finish with ${missing} unlogged ${missing===1?'set':'sets'}`,'finishConfirmed:'+a.id,'ghost')}</div></div><h2 class="review-heading">Exercises with unlogged sets</h2>${a.exercises.filter(ex=>ex.sets.some(z=>!z.done)).map(ex=>`<section class="card"><h3>${esc(ex.name)}</h3>${groupBadge(a.exercises,ex)}${tiles(ex)}</section>`).join('')}`;}
async function finish(acknowledgedId=null){if(finishBusy)return;const id=s.active?.id;if(!id)return;finishBusy=true;try{let ended=null,needsReview=false;if(await change(st=>{if(st.active?.id!==id)return st;const now=Date.now(),auto=isExpired(st,now);if(!auto&&planned(st.active)>total(st.active)&&acknowledgedId!==id){needsReview=true;return st;}ended=finishSession(st,id,now,auto);return st;},false)){if(needsReview){page='finishReview';}else if(ended){summary=ended.id;page='summary';selected=s.next;}else{page='training';}render();window.scrollTo(0,0);}}finally{finishBusy=false;}}
async function downloadBackup(){const state=clone(s);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='training-log-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
async function action(raw){const [type,a,b,c,d]=raw.split(':');if(type==='go')return go(a);
 if(type==='resume'){if(editor&&['editor','exercisePicker'].includes(page)&&!confirm('Discard unsaved edits?'))return;editor=null;await expire();if(s.active){page='active';}render();return;}
 if(type==='choose'){selected=Number(a);render();return;}
 if(type==='start')return start(Number(a));if(type==='finish')return finish();if(type==='finishConfirmed')return finish(a);
 if(type==='compare'){comparison=a;await activeChange(()=>{},false);render();return;}
 if(type==='restReset')return activeChange(w=>{w.restStarted=Date.now();});
 if(type==='expand'){const i=Number(a);expanded.has(i)?expanded.delete(i):expanded.add(i);await activeChange(()=>{},false);render();return;}
 if(type==='expandAll'||type==='collapseAll'){expanded=type==='expandAll'?new Set(s.active.exercises.map((_,i)=>i)):new Set();render();return;}
 if(type==='adjust'){return activeChange((w,st)=>{const ex=w.exercises[Number(a)],z=ex.sets[Number(b)];const step=ex.increment??(Object.hasOwn(st.settings.overrides,ex.name)?st.settings.overrides[ex.name]:st.settings.increment);z[c]=Math.max(0,c==='weight'?Math.round((z.weight+Number(d)*step)*1e6)/1e6:Math.min(999,z.reps+Number(d)));});}
 if(type==='log'){const inputs=[...document.querySelectorAll(`[data-set^="${a}:${b}:"]`)];if(inputs.some(x=>!x.value.trim()||!x.checkValidity())){inputs.find(x=>!x.value.trim()||!x.checkValidity()).reportValidity();return flash('Enter valid weight and reps');}const desired=!s.active.exercises[Number(a)].sets[Number(b)].done;return activeChange(w=>{updateSet({active:w,settings:s.settings},w.id,Number(a),Number(b),'done',desired,Date.now());});}
 if(type==='history'){historyReturn='history';detail=a;render();window.scrollTo(0,0);return;}
 if(type==='historyBack'){detail=null;if(['exercises','progress'].includes(historyReturn))page=historyReturn;historyReturn='history';render();return;}
 if(type==='done'){summary=null;page='training';render();window.scrollTo(0,0);return;}
 if(type==='reorderSessions'){if(s.active)return flash('Finish your workout before reordering sessions');orderDraft={indices:sessionOrder(s),original:sessionOrder(s),ids:s.templates.map(t=>t.id??null),labels:clone(s.templates.map(t=>({name:t.name,enabled:t.enabled}))),next:s.next};page='sessionOrder';render();window.scrollTo(0,0);return;}
 if(type==='orderMove'){if(!orderDraft)return;const i=Number(a),j=i+Number(b);if(j<0||j>=orderDraft.indices.length||i<0||i>=orderDraft.indices.length)return;[orderDraft.indices[i],orderDraft.indices[j]]=[orderDraft.indices[j],orderDraft.indices[i]];render();return;}
 if(type==='cancelOrder'){orderDraft=null;failedMutation=null;saveError='';page='training';render();return;}
 if(type==='saveOrder'){if(!orderDraft)return;const draft=clone(orderDraft);if(await change(st=>saveSessionOrder(st,draft.indices,{originalOrder:draft.original,templateIds:draft.ids}),false)){orderDraft=null;page='training';render();window.scrollTo(0,0);flash('Session order saved');}return;}
 if(type==='progressPeriod'){progressDays=Number(a);render();return;}
 if(type==='progressWorkout'){historyReturn='progress';detail=a;page='history';render();window.scrollTo(0,0);return;}
 if(type==='exerciseList'){exerciseList=a;render();return;}
 if(type==='exerciseDetail'){const entry=catalogue.find(x=>x.index===Number(a));if(!entry)return;exerciseFocus=clone(entry.exercise);exercisePhase='all';page='exercises';render();window.scrollTo(0,0);return;}
 if(type==='exerciseBack'){exerciseFocus=null;render();return;}
 if(type==='exercisePhase'){exercisePhase=a;render();return;}
 if(type==='exerciseWorkout'){historyReturn='exercises';detail=a;page='history';render();window.scrollTo(0,0);return;}
 if(type==='pickExercise'){if(!editor||editor.history)return;snapshotEditor();pickerTarget=a==='replace'?Number(b):null;pickerQuery='';page='exercisePicker';render();window.scrollTo(0,0);return;}
 if(type==='pickerBack'){pickerTarget=null;page='editor';render();return;}
 if(type==='pickKnown'){const entry=catalogue.find(x=>x.index===Number(a));if(entry)chooseLibraryExercise(entry.exercise);return;}
 if(['groupSelected','ungroupSelected','groupClear'].includes(type)){if(!editor||editor.history)return;const f=new FormData($('editor'));snapshotEditor();const exercises=editor.draft.exercises;let indices=exercises.flatMap((ex,i)=>f.has('group-select-'+i)?[i]:[]);if(type==='groupClear'){const g=exerciseGroup(exercises,exercises[Number(a)]);if(!g)return;indices=exercises.flatMap((ex,i)=>ex.group===g.id?[i]:[]);}if(type==='groupSelected'){if(indices.length<2)return flash('Select at least two exercises');groupExercises(exercises,indices,crypto.randomUUID());}else{if(!indices.length)return flash('Select an exercise to ungroup');ungroupExercises(exercises,indices);}render();const panel=document.querySelector('.group-editor');if(panel)panel.open=true;return;}
 if(type==='editToday'){await expire();if(!s.active){render();return;}editor={active:s.active.id,original:clone(s.active),originalTemplate:clone(s.templates[s.active.templateIndex]),draft:clone(s.active)};page='editor';render();window.scrollTo(0,0);return;}
 if(['todayAdd','todayMove','todayRemove','todayReplace','todaySet'].includes(type)){if(!editor?.active)return;snapshotTodayEditor();const list=editor.draft.exercises,i=Number(a),ex=list[i];if(type==='todayAdd')list.push({id:crypto.randomUUID(),name:'New exercise',sets:Array.from({length:3},()=>({weight:0,reps:10,done:false}))});if(type==='todayMove'){const j=i+Number(b);if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];}if(type==='todayRemove'||type==='todayReplace'){if(ex.sets.some(z=>z.done)&&!confirm('This exercise has logged sets. '+(type==='todayRemove'?'Remove it and its logged sets from today’s workout?':'Replace it and remove its logged sets from today’s workout?')))return;if(type==='todayRemove')list.splice(i,1);else list[i]={id:crypto.randomUUID(),...(ex.group?{group:ex.group}:{}),name:'Replacement exercise',sets:Array.from({length:ex.sets.length},()=>({weight:0,reps:10,done:false}))};}if(type==='todaySet'){if(b==='add'&&ex.sets.length<12){const last=ex.sets.at(-1);ex.sets.push({weight:last?.weight??0,reps:last?.reps??10,done:false});}if(b==='remove'&&ex.sets.length>1){if(ex.sets.at(-1).done&&!confirm('Remove this logged set from today’s workout?'))return;ex.sets.pop();}}render();return;}
 if(type==='addSession'){editor={isNew:true,index:s.templates.length,draft:{id:crypto.randomUUID(),name:'Session '+(enabledIndices(s).length+1),enabled:true,example:false,...(s.programme.mode==='manual'?{phase:null}:{}),exercises:[]}};page='editor';render();window.scrollTo(0,0);return;}
 if(type==='duplicate'){if(s.templates.length>=50)return flash('Maximum 50 sessions');editor={isNew:true,isCopy:true,index:s.templates.length,draft:duplicateSessionDraft(s,Number(a),crypto.randomUUID())};page='editor';render();window.scrollTo(0,0);return;}
 if(type==='pauseSession'){await change(st=>toggleSession(st,Number(a)),false);selected=s.next;page='training';editor=null;render();return;}
 if(type==='edit'||type==='correct'){editor=type==='edit'?{index:Number(a),draft:clone(s.templates[Number(a)])}:{history:a,draft:clone(s.history.find(w=>w.id===a))};page='editor';render();window.scrollTo(0,0);return;}
 if(type==='cancelEdit'){const old=editor;editor=null;page=old.active?'active':old.history?'history':'training';render();return;}
 if(['move','remove','add'].includes(type)){snapshotEditor();if(type==='add')editor.draft.exercises.push({id:crypto.randomUUID(),name:'New exercise',sets:3,reps:10,weight:0});if(type==='remove')editor.draft.exercises.splice(Number(a),1);if(type==='move'){const i=Number(a),j=i+Number(b);[editor.draft.exercises[i],editor.draft.exercises[j]]=[editor.draft.exercises[j],editor.draft.exercises[i]];}render();return;}
 if(type==='theme'||type==='unit'){await change(st=>{st.settings[type]=a;return st;});return;}
 if(type==='backup')return downloadBackup();if(type==='retry'){const previousActive=s.active?.id;const editing=editor;if(await change(failedMutation||(st=>st),false)){if(previousActive&&!s.active){summary=previousActive;page='summary';selected=s.next;}else if(orderDraft&&page==='sessionOrder'){orderDraft=null;page='training';}else if(editing){editor=null;page=editing.active?'active':editing.history?'history':'training';}render();}return;}
}
document.addEventListener('toggle',e=>{const panel=e.target;if(page!=='active'||panel.isConnected===false||panel.dataset?.previous===undefined)return;const i=Number(panel.dataset.previous);panel.open?referenceOpen.add(i):referenceOpen.delete(i);},true);
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(btn){action(btn.dataset.action).catch(fail);}});
document.addEventListener('input',e=>{const input=e.target;if(input.name==='query'&&['exercise-search','picker-search'].includes(input.form?.id)){if(input.form.id==='exercise-search'){exerciseQuery=input.value;$('exercise-results').innerHTML=exerciseLibraryResults();}else{pickerQuery=input.value;$('picker-results').innerHTML=exercisePickerResults();}return;}if(!input.dataset.set)return;const [i,j,key]=input.dataset.set.split(':').map((v,k)=>k<2?Number(v):v);if(!input.value.trim()||!input.checkValidity())return;const n=Number(input.value);if(!Number.isFinite(n)||n<0||key==='reps'&&!Number.isInteger(n))return;activeChange(w=>{const z=w.exercises[i].sets[j];if(z.done&&key==='reps'&&n<1)throw Error('A logged set needs at least one rep');z[key]=key==='weight'?base(n):n;},false);});
document.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='exercise-search'||e.target.id==='picker-search'){const q=String(new FormData(e.target).get('query')||'').trim();if(e.target.id==='exercise-search')exerciseQuery=q;else pickerQuery=q;render();return;}if(e.target.id==='custom-exercise'){const name=String(new FormData(e.target).get('name')||'').trim();if(!name||name.length>120)return flash('Enter an exercise name');chooseLibraryExercise({id:crypto.randomUUID(),name,sets:3,reps:10,weight:0});return;}if(e.target.id==='programme-mode'){const mode=new FormData(e.target).get('mode');if(s.active)return flash('Finish your workout before changing the rotation');if(await change(st=>setProgrammeMode(st,mode)))flash('Training structure saved');return;}if(e.target.id==='preferences'){const f=new FormData(e.target);if(await change(st=>{st.settings.restTimer=f.has('restTimer');st.settings.increment=base(Number(f.get('increment')));st.settings.inactivityHours=Number(f.get('inactivityHours'));return st;}))flash('Preferences saved');}
 if(e.target.id==='editor'){snapshotEditor();const old=editor,draft=clone(editor.draft);if(!old.history)cleanExerciseGroups(draft.exercises);if(old.active){const permanent=e.submitter?.value==='programme';if(await change(st=>saveWorkoutEdits(st,old.active,draft,Date.now(),permanent,old.original,old.originalTemplate),false)){editor=null;expanded=new Set([0]);referenceOpen=new Set();page='active';render();window.scrollTo(0,0);flash(permanent?'Today and programme updated':'Changes saved for today');}return;}if(!draft.name||draft.exercises.some(x=>!x.name))return flash('Give each exercise a name');if(!old.history&&!draft.exercises.length)return flash('Keep at least one exercise');if(old.history&&draft.exercises.some(x=>x.sets.some(z=>z.done&&z.reps<1)))return flash('Logged sets need at least one rep');if(await change(st=>{if(old.history){const i=st.history.findIndex(w=>w.id===old.history);if(i<0)throw Error('Record no longer exists');st.history[i]=draft;}else{draft.example=false;if(old.isNew){if(st.templates.length!==old.index)throw Error('Another session was added. Cancel and reopen Add Session.');if(st.templates.length>=50)throw Error('Maximum 50 sessions');st.templates.push(draft);}else st.templates[old.index]=draft;}return st;},false)){if(old.isNew)selected=old.index;editor=null;page=old.history?'history':'training';render();window.scrollTo(0,0);flash(old.history?'Correction saved':old.isCopy?'Session copy saved':'Workout saved');}}
});
document.addEventListener('change',async e=>{if(e.target.id==='progress-phase'){progressPhase=e.target.value;render();return;}if(e.target.id==='progress-exercise'){const entry=progressCatalogue.find(x=>x.index===Number(e.target.value));if(entry)progressExercise=clone(entry.exercise);render();return;}if(e.target.id==='programme-import'){const file=e.target.files[0];if(!file)return;let data;try{data=JSON.parse(await file.text());importProgramme(clone(s),data);}catch(err){flash(err.message||'Not a valid programme file');return;}if(!confirm('Import these sessions as your programme? Your saved history is preserved. This starts a fresh rotation in the current phase.'))return;if(await change(st=>importProgramme(st,data),false)){selected=s.next;page='training';editor=null;detail=null;render();flash('Programme imported');}return;}if(e.target.id==='phase-filter'){phaseFilter=e.target.value;render();}if(e.target.id==='history-filter'){filter=e.target.value;render();}if(e.target.id==='restore'){const file=e.target.files[0];if(!file)return;let data;try{data=migrate(JSON.parse(await file.text()));}catch{return flash('Not a valid Training Log backup');}if(!confirm('Replace your programme and all workout records with this backup?'))return;if(await change(()=>data,false)){selected=s.next;page='training';editor=null;detail=null;await expire();render();flash('Backup restored');}}});
async function sync(){try{s=await read();const ended=await expire();if(ended||page==='active'&&!s.active){selected=s.next;if(!ended)page='training';}render();}catch(e){fail(e);}}
channel?.addEventListener('message',()=>{if(document.activeElement?.matches('input,select')||['editor','exercisePicker','sessionOrder'].includes(page))return;sync();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync();});window.addEventListener('pageshow',e=>{if(e.persisted)sync();});
matchMedia('(prefers-color-scheme: light)').addEventListener('change',()=>{if(s)theme();});
setInterval(()=>{if(!s?.active||document.hidden)return;for(const el of document.querySelectorAll('[data-clock]'))el.textContent=elapsed(duration(s.active));for(const el of document.querySelectorAll('[data-rest]'))el.textContent=s.active.restStarted?elapsed(Math.max(0,Date.now()-s.active.restStarted)):'—';if(Date.now()-s.active.lastActivity>=s.settings.inactivityHours*3600000)sync();},1000);
try{s=await open();selected=s.next;await expire();page=s.active?'active':page;render();if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});}catch(e){$('app').innerHTML=heading('LOCAL DATA UNAVAILABLE','Training Log')+`<div class="card"><p class="note">${esc(e.message)}. Your existing data has not been overwritten. Close other tabs, allow website storage and reload.</p>${button('Download original prototype data','recover')}${button('Reload','reload')}</div>`;document.addEventListener('click',ev=>{const a=ev.target.closest('[data-action]')?.dataset.action;if(a==='reload')location.reload();if(a==='recover'){recover().then(raw=>{if(raw){const el=document.createElement('a');el.href=URL.createObjectURL(new Blob([raw],{type:'application/json'}));el.download='training-log-original-data.json';el.click();}}).catch(()=>flash('Original data unavailable'));}});}
if('serviceWorker' in navigator&&['https:','http:'].includes(location.protocol)){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>{const check=()=>{if(reg.waiting&&!s?.active)reg.waiting.postMessage({type:'ACTIVATE'});};reg.addEventListener('updatefound',()=>reg.installing?.addEventListener('statechange',check));check();}).catch(()=>{});let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!reloading){reloading=true;location.reload();}});}

setupExerciseDrag();
